def refuse_unrecorded_kits(apps, schema_editor):
    """Kit history is the only source of active kits, so a kit with no history would vanish.

    Events need a command receipt, which cannot be invented for a past action, so existing kit
    rows are refused rather than silently dropped from obligations (fail closed).
    """
    KitInstance = apps.get_model("cya_checklists", "KitInstance")
    count = KitInstance.objects.using(schema_editor.connection.alias).count()
    if count:
        raise RuntimeError(
            f"{count} kit instance(s) exist without assignment history, which obligations need; "
            "resolve them before applying this migration (nothing was changed)"
        )


